'use strict';
// AL-REC-01: a synthetic NROM cartridge with CHR RAM whose program builds one tile per graphics source, so the CHR RAM
// tracer's classification can be checked against a known answer. Generated by the suite; nothing is stored.
//   tile 0  direct       16 bytes copied from TILE_A with LDA abs,Y / STA $2007
//   tile 1  transformed  TILE_B inverted (EOR #$FF)
//   tile 2  compressed   run-length: RLE[0] written 8 times, then RLE[1] 8 times
//   tile 3  procedural   the counter values 0..15 (TYA)
//   tile 4  direct       BITS decoded bit by bit through the carry (ASL zp / ROL zp): equal to the PRG bytes
//   tile 5  untraced     written while the trace was not running (the suite starts tracing after frame 1), copied from TILE_C
const {assemble} = require('../al-exp-02/asm6502.cjs');
const ORG = 0xc000;
function build() {
  const P = [
    {label: 'RESET'}, ['SEI'], ['CLD'], ['LDX', 'imm', 0xff], ['TXS'], ['LDA', 'imm', 0], ['STA', 'abs', 0x2000], ['STA', 'abs', 0x2001],
    {label: 'W1'}, ['BIT', 'abs', 0x2002], ['BPL', 'rel', 'W1'], {label: 'W2'}, ['BIT', 'abs', 0x2002], ['BPL', 'rel', 'W2'],
    // tile 5 first, during the untraced first frame: address $0050
    ['LDA', 'imm', 0x00], ['STA', 'abs', 0x2006], ['LDA', 'imm', 0x50], ['STA', 'abs', 0x2006],
    ['LDY', 'imm', 0], {label: 'L5'}, ['LDA', 'absy', 'TILE_C'], ['STA', 'abs', 0x2007], ['INY'], ['CPY', 'imm', 16], ['BNE', 'rel', 'L5'],
    // wait for the next frame: the suite starts tracing there
    {label: 'W3'}, ['BIT', 'abs', 0x2002], ['BPL', 'rel', 'W3'], {label: 'W4'}, ['BIT', 'abs', 0x2002], ['BPL', 'rel', 'W4'],
    ['LDA', 'imm', 0x00], ['STA', 'abs', 0x2006], ['STA', 'abs', 0x2006],
    ['LDY', 'imm', 0], {label: 'L0'}, ['LDA', 'absy', 'TILE_A'], ['STA', 'abs', 0x2007], ['INY'], ['CPY', 'imm', 16], ['BNE', 'rel', 'L0'],
    ['LDY', 'imm', 0], {label: 'L1'}, ['LDA', 'absy', 'TILE_B'], ['EOR', 'imm', 0xff], ['STA', 'abs', 0x2007], ['INY'], ['CPY', 'imm', 16], ['BNE', 'rel', 'L1'],
    ['LDA', 'abs', 'RLE'], ['LDY', 'imm', 8], {label: 'L2a'}, ['STA', 'abs', 0x2007], ['DEY'], ['BNE', 'rel', 'L2a'],
    ['LDA', 'abs', {label: 'RLE', add: 1}], ['LDY', 'imm', 8], {label: 'L2b'}, ['STA', 'abs', 0x2007], ['DEY'], ['BNE', 'rel', 'L2b'],
    ['LDY', 'imm', 0], {label: 'L3'}, ['TYA'], ['STA', 'abs', 0x2007], ['INY'], ['CPY', 'imm', 16], ['BNE', 'rel', 'L3'],
    ['LDY', 'imm', 0], {label: 'L4'}, ['LDA', 'absy', 'BITS'], ['STA', 'zp', 0x10], ['LDA', 'imm', 0], ['STA', 'zp', 0x11], ['LDX', 'imm', 8],
    {label: 'L4b'}, ['ASL', 'zp', 0x10], ['ROL', 'zp', 0x11], ['DEX'], ['BNE', 'rel', 'L4b'], ['LDA', 'zp', 0x11], ['STA', 'abs', 0x2007], ['INY'], ['CPY', 'imm', 16], ['BNE', 'rel', 'L4'],
    {label: 'IDLE'}, ['JMP', 'abs', 'IDLE'],
    {label: 'NMI'}, ['RTI'],
  ];
  const code = assemble(ORG, P, {TILE_A: 0xe000, TILE_B: 0xe010, RLE: 0xe020, BITS: 0xe030, TILE_C: 0xe040});
  const prg = new Uint8Array(16384).fill(0xea); prg.set(code.bytes, 0);
  const data = {TILE_A: [0x3c, 0x42, 0x81, 0xa5, 0x81, 0x99, 0x42, 0x3c, 0x00, 0x3c, 0x7e, 0x5a, 0x7e, 0x66, 0x3c, 0x00], TILE_B: [0x01, 0x03, 0x07, 0x0f, 0x1f, 0x3f, 0x7f, 0xff, 0x80, 0xc0, 0xe0, 0xf0, 0xf8, 0xfc, 0xfe, 0xff],
    RLE: [0x5a, 0xa5], BITS: [0x10, 0x38, 0x7c, 0xfe, 0x7c, 0x38, 0x10, 0x00, 0xee, 0x44, 0x28, 0x10, 0x28, 0x44, 0xee, 0x01], TILE_C: [0x18, 0x24, 0x42, 0x81, 0x81, 0x42, 0x24, 0x18, 0xff, 0x00, 0xff, 0x00, 0xff, 0x00, 0xff, 0x00]};
  const at = {TILE_A: 0x2000, TILE_B: 0x2010, RLE: 0x2020, BITS: 0x2030, TILE_C: 0x2040};
  for (const [k, v] of Object.entries(data)) prg.set(v, at[k]);
  const L = code.labels; prg.set([L.NMI & 0xff, L.NMI >> 8, L.RESET & 0xff, L.RESET >> 8, L.NMI & 0xff, L.NMI >> 8], 0x3ffa);
  const rom = new Uint8Array(16 + 16384); rom.set([0x4e, 0x45, 0x53, 0x1a, 1, 0, 0x00, 0]); rom.set(prg, 16);
  const file = k => 16 + at[k];
  return {rom, data, file, expected: {0: {class: 'direct', offsets: [file('TILE_A')]}, 1: {class: 'transformed', transform: 'inverted'}, 2: {class: 'compressed'}, 3: {class: 'procedural'}, 4: {class: 'direct', offsets: [file('BITS')]}, 5: {class: 'untraced', located: 'verbatim', offsets: [file('TILE_C')]}}};
}
module.exports = {build};
